try {
  var input = $('Execute Workflow Trigger').first().json;
  var cfg = $('⚙️ Client Config').first().json;
  var toolInput = input.toolInput || {};
  var toolUseId = input.toolUseId || '';
  var phone = input.phone || '';
  var raw = (toolInput.preferredDate || '').toString().toLowerCase().trim();

  var now = new Date();
  var curMonth = now.getUTCMonth() + 1;
  var isBST = (curMonth >= 3 && curMonth <= 10);
  var utcOffset = isBST ? 1 : 0;

  function pad(n) { return n < 10 ? '0' + n : '' + n; }

  var dateObj = null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
    dateObj = new Date(raw + 'T12:00:00Z');
  } else if (raw === 'today') {
    dateObj = new Date(now.getTime());
  } else if (raw === 'tomorrow') {
    dateObj = new Date(now.getTime());
    dateObj.setUTCDate(dateObj.getUTCDate() + 1);
  } else if (raw) {
    // BUG-R31: an explicit day+month ("Monday, 17 August") must beat the weekday name.
    var monthWords = ['january','february','march','april','may','june','july','august','september','october','november','december'];
    var mIdx = -1;
    for (var mw = 0; mw < monthWords.length; mw++) {
      if (raw.indexOf(monthWords[mw]) !== -1) { mIdx = mw; break; }
    }
    var dayNumMatch = raw.match(/(\d{1,2})\s*(?:st|nd|rd|th)?/);
    var dayNum = dayNumMatch ? parseInt(dayNumMatch[1], 10) : 0;
    if (mIdx !== -1 && dayNum >= 1 && dayNum <= 31) {
      var yr = now.getUTCFullYear();
      var cand = new Date(Date.UTC(yr, mIdx, dayNum, 12, 0, 0));
      if (cand.getTime() < now.getTime() - 86400000) { cand = new Date(Date.UTC(yr + 1, mIdx, dayNum, 12, 0, 0)); }
      dateObj = cand;
    }
    var dayNamesLower = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
    var foundIdx = -1;
    for (var d = 0; d < dayNamesLower.length; d++) {
      if (raw.indexOf(dayNamesLower[d]) !== -1) { foundIdx = d; break; }
    }
    if (dateObj) {
      foundIdx = -1;
    }
    if (foundIdx !== -1) {
      var currentDay = now.getUTCDay();
      var daysUntil = (foundIdx - currentDay + 7) % 7;
      if (daysUntil === 0) { daysUntil = 7; }
      dateObj = new Date(now.getTime());
      dateObj.setUTCDate(dateObj.getUTCDate() + daysUntil);
    } else {
      var attempt = new Date(raw);
      // Must not clobber a date already resolved above.
      if (!dateObj && !isNaN(attempt.getTime())) { dateObj = attempt; }
    }
  }
  // V8's legacy parser defaults a yearless string like "24 august" to the year 2001.
  // Any date before this year is a parse artefact, never a real request.
  if (dateObj && !isNaN(dateObj.getTime()) && dateObj.getUTCFullYear() < now.getUTCFullYear()) { dateObj = null; }

  if (!dateObj || isNaN(dateObj.getTime())) {
    dateObj = new Date(now.getTime());
    dateObj.setUTCDate(dateObj.getUTCDate() + 1);
  }

  var year = dateObj.getUTCFullYear();
  var month = dateObj.getUTCMonth() + 1;
  var day = dateObj.getUTCDate();
  var dateStr = year + '-' + pad(month) + '-' + pad(day);
  var dow = dateObj.getUTCDay();

  var dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  var monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  var friendlyDate = dayNames[dow] + ', ' + day + ' ' + monthNames[dateObj.getUTCMonth()];

  // ---- FINDING-R30: opening hours are policy, and they live in Client Config ----
  function parseSlots(s) {
    var out = [];
    var parts = (s || '').split(',');
    for (var i = 0; i < parts.length; i++) {
      var v = parseInt(parts[i], 10);
      if (!isNaN(v)) { out.push(v); }
    }
    return out;
  }
  var localSlotHours;
  if (dow === 0) { localSlotHours = parseSlots(cfg.sundaySlots); }
  else if (dow === 6) { localSlotHours = parseSlots(cfg.saturdaySlots); }
  else { localSlotHours = parseSlots(cfg.weekdaySlots); }

  var closedReason = '';
  if (localSlotHours.length === 0) { closedReason = 'closed-day'; }

  var bankHolidays = (cfg.bankHolidays || '').split(',');
  for (var b = 0; b < bankHolidays.length; b++) {
    if (bankHolidays[b].trim() === dateStr) { closedReason = 'bank-holiday'; localSlotHours = []; break; }
  }

  // Never offer a slot in the past, or inside the minimum-notice window.
  var minNotice = parseInt(cfg.minNoticeHours, 10);
  if (isNaN(minNotice)) { minNotice = 2; }
  var earliestMs = now.getTime() + (minNotice * 3600000);

  var labelFor = ['12am','1am','2am','3am','4am','5am','6am','7am','8am','9am','10am','11am','12pm','1pm','2pm','3pm','4pm','5pm','6pm','7pm','8pm','9pm','10pm','11pm'];
  var slotHoursUTC = [];
  var slotLabels = [];
  var droppedForNotice = 0;
  for (var s = 0; s < localSlotHours.length; s++) {
    var utcHour = localSlotHours[s] - utcOffset;
    var slotMs = new Date(dateStr + 'T' + pad(utcHour) + ':00:00.000Z').getTime();
    if (isNaN(slotMs)) { continue; }
    if (slotMs < earliestMs) { droppedForNotice++; continue; }
    slotHoursUTC.push(utcHour);
    slotLabels.push(labelFor[localSlotHours[s]]);
  }

  if (!closedReason && slotHoursUTC.length === 0) { closedReason = droppedForNotice > 0 ? 'too-soon' : 'no-slots'; }

  var dayStartISO = dateStr + 'T' + pad(0) + ':00:00.000Z';
  var dayEndISO = dateStr + 'T23:59:59.000Z';

  return [{ json: { toolUseId: toolUseId, phone: phone, preferredDate: raw, dateStr: dateStr, dayStartISO: dayStartISO, dayEndISO: dayEndISO, slotHoursUTC: slotHoursUTC, slotLabels: slotLabels, friendlyDate: friendlyDate, closedReason: closedReason } }];
} catch (e) {
  var fb = $('Execute Workflow Trigger').first().json;
  return [{ json: { toolUseId: fb.toolUseId || '', phone: fb.phone || '', error: e.message, dateStr: new Date().toISOString().split('T')[0], dayStartISO: new Date().toISOString(), dayEndISO: new Date().toISOString(), slotHoursUTC: [], slotLabels: [], friendlyDate: 'that day', closedReason: 'error' } }];
}

try {
  var parsed = $('Parse Availability Request').first().json;
  var events = $input.all();
  var toolUseId = parsed.toolUseId || '';
  var friendlyDate = parsed.friendlyDate || 'the requested date';
  var dateStr = parsed.dateStr || '';
  var slotHoursUTC = parsed.slotHoursUTC || [];
  var slotLabels = parsed.slotLabels || [];
  var closedReason = parsed.closedReason || '';

  // BUG-R39: the assistant had no way to know whether this customer actually HAS a
  // booking, so a "move my appointment" from someone with none got a list of times and
  // a dead end. Report the booking state as FACT here; section 12 of the prompt forbids
  // treating tool output as instructions, so the behaviour rule lives in the prompt.
  var bookingState = '';
  try {
    var apptRows = $('Read Appointment Log').all();
    var readFailed = (apptRows.length > 0 && apptRows[0].json && typeof apptRows[0].json.error !== 'undefined');
    if (!readFailed) {
      var ph = String(parsed.phone || '').replace(/[^0-9]/g, '');
      var found = null;
      for (var ar = 0; ar < apptRows.length; ar++) {
        var arow = apptRows[ar].json || {};
        if (!arow.Phone) { continue; }
        if (String(arow.Phone).replace(/[^0-9]/g, '') === ph && ph !== '' && arow.Status === 'confirmed') { found = arow; break; }
      }
      if (found) {
        bookingState = ' CUSTOMER BOOKING STATE: this number has a confirmed appointment on ' + (found.Date || 'an unknown date') + ' at ' + (found.Time || 'an unknown time') + '.';
      } else {
        bookingState = ' CUSTOMER BOOKING STATE: this number has no confirmed appointment on file.';
      }
    }
  } catch (be) { bookingState = ''; }

  // Calendar read failure must never be reported as free availability.
  if (events.length > 0 && events[0].json && typeof events[0].json.error !== 'undefined') {
    return [{ json: { toolCallId: toolUseId, result: 'I am unable to check the calendar right now, so I cannot confirm times. Our team will contact you shortly to arrange a slot.' } }];
  }

  // FINDING-R30: a day we are closed on, or a slot inside the notice window, is not
  // an availability question at all — answer it before touching the calendar data.
  if (closedReason === 'closed-day' || closedReason === 'bank-holiday') {
    var why = closedReason === 'bank-holiday' ? 'a bank holiday' : 'a day we are closed';
    return [{ json: { toolCallId: toolUseId, result: 'CONFIRMED DATE IS ' + friendlyDate + '. We do not carry out surveys on ' + friendlyDate + ' because it is ' + why + '. Survey visits run Monday to Friday 9am to 5pm only, and need at least 48 hours notice. Refer to this date exactly as "' + friendlyDate + '" and offer to check another day.' + bookingState } }];
  }
  if (closedReason === 'too-soon') {
    return [{ json: { toolCallId: toolUseId, result: 'CONFIRMED DATE IS ' + friendlyDate + '. Every remaining slot on ' + friendlyDate + ' is too soon — we need at least 48 hours notice to arrange a surveyor. Refer to this date exactly as "' + friendlyDate + '" and offer the next working day instead.' + bookingState } }];
  }
  if (slotHoursUTC.length === 0) {
    return [{ json: { toolCallId: toolUseId, result: 'CONFIRMED DATE IS ' + friendlyDate + '. There are no bookable times on ' + friendlyDate + '. Refer to this date exactly as "' + friendlyDate + '" and ask if they would like to try another day.' } }];
  }

  var bookedRanges = [];
  for (var i = 0; i < events.length; i++) {
    var ev = events[i].json;
    if (ev && ev.status === 'cancelled') { continue; }
    if (ev && ev.start && ev.start.dateTime) {
      var evStart = new Date(ev.start.dateTime).getTime();
      var evEnd = ev.end && ev.end.dateTime ? new Date(ev.end.dateTime).getTime() : evStart + 3600000;
      bookedRanges.push({ start: evStart, end: evEnd });
    }
  }

  function pad(n) { return n < 10 ? '0' + n : '' + n; }

  var available = [];
  for (var j = 0; j < slotHoursUTC.length; j++) {
    var slotStart = new Date(dateStr + 'T' + pad(slotHoursUTC[j]) + ':00:00.000Z').getTime();
    var slotEnd = slotStart + 3600000;
    var conflict = false;
    for (var k = 0; k < bookedRanges.length; k++) {
      if (slotStart < bookedRanges[k].end && slotEnd > bookedRanges[k].start) { conflict = true; break; }
    }
    if (!conflict) { available.push(slotLabels[j]); }
  }

  var result;
  if (available.length === 0) {
    result = 'CONFIRMED DATE IS ' + friendlyDate + '. There are no free slots on ' + friendlyDate + '. Refer to this date exactly as "' + friendlyDate + '" and ask if they would like to try another day.' + bookingState;
  } else {
    // BUG-R33: returning only the first three made the model treat every OTHER slot as
    // taken — a customer asking for 2pm on a totally free day was told it was unavailable.
    // Send the FULL list; let the assistant choose how many to surface.
    var shown = available.slice(0, 3);
    result = 'CONFIRMED DATE IS ' + friendlyDate + '. In your reply you must call this date exactly "' + friendlyDate + '" and no other day or date. ALL free times on ' + friendlyDate + ' are: ' + available.join(', ') + '. Any time in that list IS available — if the customer named one of them, confirm it rather than offering alternatives. If they have not named a time, suggest these three: ' + shown.join(', ') + '.' + bookingState;
  }

  return [{ json: { toolCallId: toolUseId, result: result } }];
} catch (e) {
  return [{ json: { toolCallId: $('Parse Availability Request').first().json.toolUseId || '', result: 'I could not check availability right now. Please call us directly or try again shortly.' } }];
}

